// One shape out, whichever trigger fired.
//
// The two paths carry different things: a crash knows the workflow and the
// execution, a deliberate quarantine knows the lead. The sheet has one set of
// columns, so both are flattened here rather than in two Sheets nodes.
//
// The keys below MUST match the Quarantine tab's headers exactly - the Sheets
// node maps them by name.

const rows = [];

for (const item of $input.all()) {
  // A caller that points a webhook straight at this workflow sends the whole
  // HTTP envelope, with the real payload under `body`. Unwrap it, so the
  // quarantine works whether it is called by a workflow or by an HTTP request.
  const raw = item.json || {};
  const j = raw.body && typeof raw.body === 'object' ? raw.body : raw;
  const crashed = Boolean(j.execution && j.workflow);

  if (crashed) {
    // n8n's Error Trigger payload.
    const error = j.execution.error || {};
    rows.push({
      failed_at: new Date().toISOString(),
      source: `crash in "${j.workflow.name || 'unknown workflow'}"`,
      email: '',
      company: '',
      // n8n reports the failing node as `lastNodeExecuted`; `error.node` is not
      // always present, so both are tried before giving up.
      failed_step: j.execution.lastNodeExecuted || error.node?.name || 'unknown step',
      error: String(error.message || 'no message').slice(0, 500),
      // The execution link is the fastest way back to what actually happened.
      raw_payload: j.execution.url || `execution ${j.execution.id || '?'}`,
      status: 'new',
    });
    continue;
  }

  // Called by the pipeline, so the lead itself is here.
  const lead = j.lead || j;
  rows.push({
    failed_at: new Date().toISOString(),
    source: j.source || lead.source || 'unknown',
    email: lead.email || '',
    company: lead.company || '',
    failed_step: j.failed_step || 'unknown step',
    error: String(j.error || 'no reason given').slice(0, 500),
    // Everything we received, so a human can replay the lead by hand.
    raw_payload: JSON.stringify(j.raw_payload || lead).slice(0, 4000),
    status: 'new',
  });
}

return rows.map((json) => ({ json }));

